import { ReserveForm } from '@/components/ReserveForm';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';

async function getBook(bookId: string) {
  return prisma.book.findUnique({
    where: { id: bookId }
  });
}

async function translateToPt(text: string): Promise<string> {
  if (!text) return text;
  try {
    const res = await fetch(
      `https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=pt&dt=t&q=${encodeURIComponent(
        text
      )}`
    );
    const data = await res.json();
    return data[0].map((item: any) => item[0]).join('');
  } catch (error) {
    console.error('Translation error:', error);
    return text; // fallback to original
  }
}

export default async function BookDetailPage({ 
  params 
}: { 
  params: Promise<{ id: string }> 
}) {
  const { id } = await params;
  const book = await getBook(id);

  if (!book) {
    return (
      <div className="container mx-auto px-4 py-8">
        <h1 className="text-2xl font-bold mb-4">Erro</h1>
        <p>Livro não encontrado.</p>
      </div>
    );
  }

  // Translate title and description dynamically on the server
  const translatedTitle = await translateToPt(book.title);
  const translatedDesc = book.description ? await translateToPt(book.description) : null;

  return (
    <div className="container mx-auto pt-32 sm:pt-40 pb-12 px-4 sm:px-10 min-h-screen">
      <div className="flex flex-col md:flex-row gap-8">
        <div className="md:w-1/3 shrink-0 flex flex-col items-center md:items-start pb-6">
          {book.coverUrl && (
            <img 
              src={book.coverUrl} 
              alt={translatedTitle} 
              className="w-full max-w-sm max-h-[75vh] object-cover rounded-lg shadow-md"
            />
          )}
        </div>

        <div className="md:w-2/3 flex flex-col">
          <div className="bg-white/60 backdrop-blur-sm border border-border/40 p-6 sm:p-8 rounded-2xl shadow-sm flex flex-col h-full">
            <h1 className="text-3xl font-bold mb-2">{translatedTitle}</h1>
            <p className="text-xl text-gray-600 mb-4">por {book.author}</p>

            {translatedDesc && (
              <p className="mb-6 text-gray-700 whitespace-pre-wrap">{translatedDesc}</p>
            )}

            <div className="mb-6 mt-auto">
              <span className={`px-3 py-1 rounded-full ${
                book.quantity > 0 ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
              }`}>
                {book.quantity > 0 ? `Disponível (${book.quantity})` : 'Indisponível'}
              </span>
            </div>

            {book.quantity > 0 && (
              <div className="bg-blue-50 p-4 rounded-lg max-w-md w-full">
                <h2 className="text-lg font-semibold mb-3">Fazer Reserva</h2>
                <ReserveForm bookId={book.id} />
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

