'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import Image from 'next/image';

interface Book {
  id: string;
  title: string;
  author: string;
  quantity: number;
  coverUrl?: string;
  genres?: string[];
  description?: string;
  publishedAt?: number;
}

export default function EditBookPage() {
  const router = useRouter();
  const params = useParams();
  const id = params.id as string;

  const [book, setBook] = useState<Book | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Genres state
  const [existingGenres, setExistingGenres] = useState<string[]>([]);
  const [showGenreSuggestions, setShowGenreSuggestions] = useState(false);

  useEffect(() => {
    async function fetchData() {
      try {
        // 1. Fetch Book Details
        const bookRes = await fetch(`/api/livros/${id}`);
        if (!bookRes.ok) throw new Error('Failed to fetch book');
        const bookData = await bookRes.json();
        setBook(bookData);

        // 2. Fetch Genres for suggestions
        const genreRes = await fetch('/api/genres');
        if (genreRes.ok) {
            const genreData = await genreRes.json();
            setExistingGenres(genreData);
        }
      } catch (e) {
        console.error("Failed to fetch data", e);
        // If critical failure, fallback or show error
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, [id]);

  const handleDelete = async () => {
      if (!confirm('Tem certeza que deseja EXCLUIR este livro? Esta ação não pode ser desfeita.')) return;

      setDeleting(true);
      try {
          const res = await fetch(`/api/livros/${id}`, { method: 'DELETE' });
          if (res.ok) {
              alert('Livro excluído com sucesso.');
              router.push('/admin/livros');
              router.refresh();
          } else {
              const err = await res.json();
              alert(err.error || 'Erro ao excluir livro.');
          }
      } catch (e) {
          alert('Erro ao excluir.');
      } finally {
          setDeleting(false);
      }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!book) return;

    setSaving(true);
    try {
      let coverUrl = book.coverUrl;

      // 1. Upload File if selected
      if (selectedFile) {
        const formData = new FormData();
        formData.append('file', selectedFile);

        const uploadRes = await fetch('/api/upload', {
          method: 'POST',
          body: formData
        });

        if (!uploadRes.ok) throw new Error('Falha no upload da imagem');

        const data = await uploadRes.json();
        coverUrl = data.url;
      }

      // 2. Update Book
      const response = await fetch('/api/livros/update', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...book, coverUrl }),
      });

      if (response.ok) {
        router.push('/admin/livros');
        router.refresh();
      } else {
        alert('Erro ao atualizar livro');
      }
    } catch (error) {
      console.error(error);
      alert('Erro ao atualizar');
    } finally {
      setSaving(false);
    }
  };

  if (loading) return <div className="p-8 text-center">Carregando...</div>;
  if (!book) return <div className="p-8 text-center text-red-600">Livro não encontrado (ID inválido ou erro de conexão).</div>;

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold text-gray-800">Editar Livro</h1>
          <button 
            type="button" 
            onClick={handleDelete}
            disabled={deleting}
            className="text-red-600 hover:text-red-800 text-sm font-medium border border-red-200 px-3 py-1 rounded hover:bg-red-50"
          >
              {deleting ? 'Excluindo...' : 'Excluir Livro'}
          </button>
      </div>

      <form onSubmit={handleSave} className="bg-white p-6 rounded-lg shadow space-y-4">

        {/* Title */}
        <div>
          <label className="block text-sm font-medium text-gray-700">Título</label>
          <input
            type="text"
            value={book.title}
            onChange={e => setBook({ ...book, title: e.target.value })}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
          />
        </div>

        {/* Author */}
        <div>
          <label className="block text-sm font-medium text-gray-700">Autor</label>
          <input
            type="text"
            value={book.author}
            onChange={e => setBook({ ...book, author: e.target.value })}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
          />
        </div>

        {/* Genres */}
        <div className="relative z-20"> 
          <label className="block text-sm font-medium text-gray-700">Gêneros / Assuntos</label>
           <div className="relative flex flex-wrap gap-2 p-2 border border-gray-300 rounded focus-within:ring-2 focus-within:ring-indigo-500 bg-white min-h-[42px]">
              {(book.genres || []).map((g, idx) => (
                  <span key={idx} className="bg-indigo-100 text-indigo-700 px-2 py-1 rounded text-xs flex items-center gap-1">
                      {g}
                      <button 
                          type="button"
                          onClick={() => setBook({...book, genres: (book.genres || []).filter((_, i) => i !== idx)})}
                          className="hover:text-indigo-900 font-bold"
                      >
                          ×
                      </button>
                  </span>
              ))}
              <div className="relative flex-1 min-w-[100px]">
                  <input
                      type="text"
                      placeholder={(book.genres || []).length === 0 ? "Ex: Fantasia (Enter para adicionar)" : ""}
                      onChange={(e) => {
                          setShowGenreSuggestions(true);
                      }}
                       onFocus={() => setShowGenreSuggestions(true)}
                      onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ',') {
                              e.preventDefault();
                              const val = e.currentTarget.value.trim();
                              if (val) {
                                  setBook(prev => prev ? ({
                                      ...prev, 
                                      genres: [...(prev.genres || []), val]
                                  }) : null);
                                  e.currentTarget.value = '';
                                  setShowGenreSuggestions(false);
                              }
                          }
                      }}
                      onBlur={(e) => {
                          const val = e.currentTarget.value.trim();
                          // Delay to allow click
                          setTimeout(() => {
                              setShowGenreSuggestions(false);
                              if (val) {
                                  setBook(prev => prev ? ({
                                      ...prev, 
                                      genres: [...(prev.genres || []), val]
                                  }) : null);
                                  e.target.value = '';
                              }
                          }, 200);
                      }}
                      className="w-full h-full outline-none text-sm bg-transparent"
                  />
                  {showGenreSuggestions && (
                      <ul className="absolute left-0 bottom-full mb-1 w-full bg-white border border-gray-200 rounded shadow-lg max-h-40 overflow-y-auto z-10">
                          {existingGenres
                              .filter(g => !book.genres?.includes(g)) // Filter already added
                              // Simple client filter if user types. But input value is hard to get here cleanly without controlled state.
                              // Let's just show all or rely on browser? No, let's make it controlled if needed or just show all available.
                              // For simplicity in Edit (using uncontrolled input for now), showing all available not yet added.
                              .map((g, i) => (
                              <li 
                                  key={i}
                                  onMouseDown={(e) => {
                                      e.preventDefault();
                                      setBook(prev => prev ? ({
                                          ...prev, 
                                          genres: [...(prev.genres || []), g]
                                      }) : null);
                                      // Clear input? Hard without ref or state. 
                                      // Using document.activeElement modification is hacky.
                                      // RECOMMENDATION: Switch EditPage to use controlled input for cleaner logic, but for now this works for clicking.
                                      // We need to clear the input value manually if we want perfection, but let's assume user keeps typing or we refresh.
                                      setShowGenreSuggestions(false);
                                  }}
                                  className="px-3 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                              >
                                  {g}
                              </li>
                          ))}
                      </ul>
                  )}
              </div>
          </div>
          <p className="text-xs text-gray-500 mt-1">
             Pressione Enter ou Vírgula para adicionar tags, ou clique na sugestão.
          </p>
        </div>

        {/* Description */}
        <div>
          <label className="block text-sm font-medium text-gray-700">Sinopse / Descrição</label>
          <textarea
            rows={4}
            value={book.description || ''}
            onChange={e => setBook({ ...book, description: e.target.value })}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
            {/* Quantity */}
            <div>
              <label className="block text-sm font-medium text-gray-700">Quantidade</label>
              <input
                type="number"
                value={book.quantity}
                onChange={e => setBook({ ...book, quantity: parseInt(e.target.value) })}
                className="mt-1 block w-full border border-gray-300 rounded-md p-2"
              />
            </div>
             {/* Year */}
             <div>
              <label className="block text-sm font-medium text-gray-700">Ano</label>
              <input
                type="number"
                value={book.publishedAt || ''}
                onChange={e => setBook({ ...book, publishedAt: parseInt(e.target.value) })}
                className="mt-1 block w-full border border-gray-300 rounded-md p-2"
              />
            </div>
        </div>

        {/* Cover Image Upload */}
        <div>
          <label className="block text-sm font-medium text-gray-700">Capa do Livro</label>
          <div className="mt-2">
            <input
              type="file"
              accept="image/*"
              onChange={(e) => {
                if (e.target.files && e.target.files[0]) {
                  setSelectedFile(e.target.files[0]);
                }
              }}
              className="block w-full text-sm text-gray-500
                file:mr-4 file:py-2 file:px-4
                file:rounded-full file:border-0
                file:text-sm file:font-semibold
                file:bg-blue-50 file:text-blue-700
                hover:file:bg-blue-100"
            />
          </div>
        </div>

        {/* Preview */}
        {(book.coverUrl || selectedFile) && (
          <div className="mt-4">
            <span className="text-sm font-medium text-gray-700">Pré-visualização:</span>
            <div className="mt-2 w-32 h-48 relative border rounded overflow-hidden bg-gray-100">
                <img 
                    src={selectedFile ? URL.createObjectURL(selectedFile) : book.coverUrl} 
                    alt="Capa" 
                    className="w-full h-full object-cover"
                    onError={(e) => {
                        (e.target as HTMLImageElement).style.display = 'none';
                    }} 
                />
            </div>
          </div>
        )}

        <div className="flex gap-3 pt-4 border-t mt-6">
          <div className="flex-1 flex gap-3">
              <button
                type="submit"
                disabled={saving}
                className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 font-medium"
              >
                {saving ? 'Salvando...' : 'Salvar Alterações'}
              </button>
              <button
                type="button"
                onClick={() => router.back()}
                className="bg-gray-100 text-gray-700 px-4 py-2 rounded hover:bg-gray-200"
              >
                Cancelar
              </button>
          </div>
        </div>

      </form>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Image from 'next/image';

interface BookSuggestion {
  title: string;
  authors: string[];
  isbn: string;
  publishedYear?: number;
  coverUrl?: string;
}

export default function NewBookPage() {
  const router = useRouter();

  // Form State
  const [formData, setFormData] = useState({
    title: '',
    author: '',
    isbn: '',
    publishedYear: '',
    quantity: 1,
    coverUrl: '',
    genres: [] as string[],
    description: ''
  });

  // Tag Input State
  const [currentGenreInput, setCurrentGenreInput] = useState('');
  const [existingGenres, setExistingGenres] = useState<string[]>([]);
  const [showGenreSuggestions, setShowGenreSuggestions] = useState(false);

  useEffect(() => {
    fetch('/api/genres')
      .then(res => res.json())
      .then(data => setExistingGenres(data))
      .catch(err => console.error("Failed to load genres", err));
  }, []);

  const [coverFile, setCoverFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  // Search/Autocomplete State
  interface ExtendedBookSuggestion extends BookSuggestion {
    workKey?: string;
    genres?: string[];
  }
  const [suggestions, setSuggestions] = useState<ExtendedBookSuggestion[]>([]);
  const [loadingSearch, setLoadingSearch] = useState(false);
  const [loadingDetails, setLoadingDetails] = useState(false); // To show spinner when fetching details
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Debounce search
  useEffect(() => {
    const delayDebounceFn = setTimeout(async () => {
      if (formData.title.length >= 3 && showSuggestions) {
        setLoadingSearch(true);
        try {
          const response = await fetch(`/api/livros/search?q=${encodeURIComponent(formData.title)}`);
          if (response.ok) {
            const data = await response.json();
            setSuggestions(data);
          }
        } catch (error) {
          console.error('Error fetching suggestions:', error);
        } finally {
          setLoadingSearch(false);
        }
      } else {
        setSuggestions([]);
      }
    }, 500);

    return () => clearTimeout(delayDebounceFn);
  }, [formData.title, showSuggestions]);

  // Click outside to close suggestions
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [wrapperRef]);

  const handleSelectBook = async (book: ExtendedBookSuggestion) => {
    // 1. Set basic info immediately
    setFormData(prev => ({
      ...prev,
      title: book.title,
      author: book.authors.join(', '),
      isbn: book.isbn,
      publishedYear: book.publishedYear?.toString() || '',
      coverUrl: book.coverUrl || '',
      genres: book.genres || [], 
    }));
    setShowSuggestions(false);

    // 2. Fetch full details (description + maybe better genre)
    if (book.workKey) {
        setLoadingDetails(true);
        try {
            const res = await fetch(`/api/livros/details?key=${book.workKey}`);
            if (res.ok) {
                const details = await res.json();
                setFormData(prev => ({
                    ...prev,
                    description: details.description || prev.description,
                    genres: details.genres && details.genres.length > 0 
                            ? Array.from(new Set([...prev.genres, ...details.genres])) // Merge unique
                            : prev.genres
                }));
            }
        } catch (e) {
            console.error(e);
        } finally {
            setLoadingDetails(false);
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.author) {
        alert('Título e Autor são obrigatórios');
        return;
    }

    try {
      let finalCoverUrl = formData.coverUrl;

      // Handle Image Upload if file exists
      if (coverFile) {
          const uploadData = new FormData();
          uploadData.append('file', coverFile);

          const uploadRes = await fetch('/api/upload', {
              method: 'POST',
              body: uploadData
          });

          if (uploadRes.ok) {
              const { url } = await uploadRes.json();
              finalCoverUrl = url;
          } else {
              alert('Erro ao fazer upload da imagem. O livro será salvo sem a capa personalizada.');
          }
      }

      const response = await fetch('/api/livros/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          coverUrl: finalCoverUrl,
          publishedYear: parseInt(formData.publishedYear) || undefined,
          quantity: parseInt(formData.quantity.toString()),
          description: formData.description || `Publicado em ${formData.publishedYear || '?'}`,
          genres: formData.genres
        }),
      });

      if (response.ok) {
        router.push('/admin/livros');
        router.refresh();
      } else {
        alert('Erro ao salvar o livro');
      }
    } catch (error) {
      console.error('Error saving book:', error);
      alert('Erro ao salvar o livro');
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Adicionar Livro</h1>

      <form onSubmit={handleSave} className="bg-white p-6 rounded-lg shadow-md space-y-4">

        {/* Title / Search Input */}
        <div className="relative" ref={wrapperRef}>
            <label className="block text-sm font-medium text-gray-700 mb-1">Título do Livro</label>
            <div className="relative">
                <input
                type="text"
                placeholder="Digite o título para buscar automático..."
                value={formData.title}
                onChange={(e) => {
                    setFormData({...formData, title: e.target.value});
                    setShowSuggestions(true);
                }}
                onFocus={() => setShowSuggestions(true)}
                className="w-full p-2 pr-8 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                autoComplete="off"
                />
                {/* Spinner inside input */}
                {(loadingSearch || loadingDetails) && (
                    <div className="absolute right-2 top-2">
                        <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-indigo-600"></div>
                    </div>
                )}
            </div>

            {/* Suggestions Dropdown */}
            {showSuggestions && suggestions.length > 0 && (
              <ul className="absolute z-50 w-full bg-white border border-gray-200 mt-1 rounded-md shadow-lg max-h-60 overflow-y-auto">
                {suggestions.map((book, index) => (
                  <li 
                    key={`${book.isbn}-${index}`}
                    onClick={() => handleSelectBook(book)}
                    className="p-3 hover:bg-indigo-50 cursor-pointer border-b last:border-b-0 flex items-center gap-3"
                  >
                    {book.coverUrl && (
                      <div className="w-8 h-12 relative shrink-0">
                        <Image src={book.coverUrl} alt={book.title} fill className="object-cover rounded" />
                      </div>
                    )}
                    <div>
                      <p className="font-medium text-gray-900 text-sm">{book.title}</p>
                      <p className="text-xs text-gray-500">{book.authors.join(', ')}</p>
                      {book.genres && book.genres.length > 0 && (
                          <div className="flex gap-1 flex-wrap mt-0.5">
                              {book.genres.slice(0, 3).map((g, i) => (
                                  <span key={i} className="text-[10px] bg-gray-100 text-gray-600 px-1 py-0.5 rounded">{g}</span>
                              ))}
                          </div>
                      )}
                    </div>
                  </li>
                ))}
              </ul>
            )}
        </div>

        {/* Other Fields - Auto-filled but editable */}
        <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Autor(es)</label>
            <input
              type="text"
              value={formData.author}
              onChange={(e) => setFormData({...formData, author: e.target.value})}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
            />
        </div>

        <div className="grid grid-cols-2 gap-4">
            <div className="relative">
                <label className="block text-sm font-medium text-gray-700 mb-1">Gêneros / Assunto</label>
                <div className="relative flex flex-wrap gap-2 p-2 border border-gray-300 rounded focus-within:ring-2 focus-within:ring-indigo-500 bg-white min-h-[42px]">
                    {formData.genres.map((g, idx) => (
                        <span key={idx} className="bg-indigo-100 text-indigo-700 px-2 py-1 rounded text-xs flex items-center gap-1">
                            {g}
                            <button 
                                type="button"
                                onClick={() => setFormData({...formData, genres: formData.genres.filter((_, i) => i !== idx)})}
                                className="hover:text-indigo-900 font-bold"
                            >
                                ×
                            </button>
                        </span>
                    ))}
                    <div className="relative flex-1 min-w-[100px]">
                        <input
                            type="text"
                            placeholder={formData.genres.length === 0 ? "Ex: Fantasia (Enter para adicionar)" : ""}
                            value={currentGenreInput}
                            onChange={(e) => {
                                setCurrentGenreInput(e.target.value);
                                setShowGenreSuggestions(true);
                            }}
                            onFocus={() => setShowGenreSuggestions(true)}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' || e.key === ',') {
                                    e.preventDefault();
                                    if (currentGenreInput.trim()) {
                                        setFormData(prev => ({
                                            ...prev, 
                                            genres: [...prev.genres, currentGenreInput.trim()]
                                        }));
                                        setCurrentGenreInput('');
                                        setShowGenreSuggestions(false);
                                    }
                                }
                            }}
                            onBlur={() => {
                                // Delay to allow click on suggestion
                                setTimeout(() => {
                                     setShowGenreSuggestions(false);
                                     if (currentGenreInput.trim()) {
                                         setFormData(prev => ({
                                            ...prev, 
                                            genres: [...prev.genres, currentGenreInput.trim()]
                                        }));
                                        setCurrentGenreInput('');
                                    }
                                }, 200);
                            }}
                            className="w-full h-full outline-none text-sm bg-transparent"
                        />
                         {/* Genre Suggestions Dropdown */}
                        {showGenreSuggestions && currentGenreInput.length > 0 && (
                            <ul className="absolute left-0 bottom-full mb-1 w-full bg-white border border-gray-200 rounded shadow-lg max-h-40 overflow-y-auto z-10">
                                {existingGenres
                                    .filter(g => g.toLowerCase().includes(currentGenreInput.toLowerCase()) && !formData.genres.includes(g))
                                    .map((g, i) => (
                                    <li 
                                        key={i}
                                        onMouseDown={(e) => {
                                            e.preventDefault(); // Prevent blur
                                            setFormData(prev => ({
                                                ...prev, 
                                                genres: [...prev.genres, g]
                                            }));
                                            setCurrentGenreInput('');
                                            setShowGenreSuggestions(false);
                                        }}
                                        className="px-3 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                                    >
                                        {g}
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                </div>
                <p className="text-xs text-gray-400 mt-1">Pressione Enter ou Vírgula para adicionar tags.</p>
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Ano de Publicação</label>
                <input
                type="number"
                value={formData.publishedYear}
                onChange={(e) => setFormData({...formData, publishedYear: e.target.value})}
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                />
            </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">ISBN</label>
                <input
                type="text"
                value={formData.isbn}
                onChange={(e) => setFormData({...formData, isbn: e.target.value})}
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                />
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Quantidade</label>
                <input
                type="number"
                min="1"
                value={formData.quantity}
                onChange={(e) => setFormData({...formData, quantity: parseInt(e.target.value)})}
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                />
            </div>
        </div>

        <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Sinopse / Descrição</label>
            <textarea
              rows={4}
              value={formData.description}
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              placeholder="Sinopse do livro..."
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-indigo-500 focus:outline-none"
            />
        </div>

        {/* Cover Preview (from API) */}
        {formData.coverUrl && !coverFile && (
            <div className="flex items-center gap-4 p-3 bg-blue-50 rounded border border-blue-100">
                <div className="h-20 w-14 relative shrink-0 border rounded overflow-hidden">
                    <Image src={formData.coverUrl} alt="Capa" fill className="object-cover" />
                </div>
                <div className="flex-1">
                    <p className="text-sm font-medium text-blue-800">Capa importada automaticamente</p>
                    <button 
                        type="button"
                        onClick={() => setFormData({...formData, coverUrl: ''})}
                        className="text-xs text-red-500 hover:underline mt-1"
                    >
                        Remover capa
                    </button>
                </div>
            </div>
        )}

        {/* Manual File Upload */}
        <div className="border-t pt-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">Upload de Capa Manual (Opcional)</label>
            <input 
                type="file" 
                accept="image/*"
                onChange={(e) => {
                    const file = e.target.files?.[0] || null;
                    setCoverFile(file);
                    // Clear API URL if user selects a file manually to avoid confusion
                    if (file) setFormData({...formData, coverUrl: ''});
                }}
                className="block w-full text-sm text-gray-500
                  file:mr-4 file:py-2 file:px-4
                  file:rounded-full file:border-0
                  file:text-sm file:font-semibold
                  file:bg-indigo-50 file:text-indigo-700
                  hover:file:bg-indigo-100"
            />
            {coverFile && (
                <p className="text-sm text-green-600 mt-2">
                    Arquivo selecionado: {coverFile.name}
                </p>
            )}
        </div>

        <div className="pt-4">
            <button
                type="submit"
                className="w-full bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700 font-medium transition-colors"
                disabled={!formData.title}
            >
                Adicionar ao Estoque
            </button>
        </div>

      </form>
    </div>
  );
}

