async function getBooks(query?: string) {
  const where = query ? {
    OR: [
      { title: { contains: query, mode: 'insensitive' as const } },
      { author: { contains: query, mode: 'insensitive' as const } }
    ]
  } : {};

  return prisma.book.findMany({
    where,
    orderBy: { createdAt: 'desc' }
  });
}

