async function getReservations(query?: string) {
  const where = query ? {
    OR: [
      { student: { name: { contains: query, mode: 'insensitive' as const } } },
      { book: { title: { contains: query, mode: 'insensitive' as const } } }
    ]
  } : {};

  return prisma.reservation.findMany({
    where,
    include: {
      book: true,
      student: true
    },
    orderBy: {
      createdAt: 'desc'
    }
  });
}

