  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded shadow mt-10">
      <h1 className="text-2xl font-bold mb-6">Adicionar Usuário Admin</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
