async function getUsers(query?: string) {
  const where = query ? {
    OR: [
      { name: { contains: query, mode: 'insensitive' as const } },
      { email: { contains: query, mode: 'insensitive' as const } }
    ]
  } : {};

  return prisma.adminUser.findMany({
    where,
    orderBy: { name: 'asc' }
  });
}

