  return (
    <div className="min-h-screen bg-muted/30 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-card rounded-2xl shadow-xl p-8 border border-border">
        <div className="text-center mb-8">
            <h1 className="text-2xl font-bold text-foreground">Bem-vindo de volta! 👋</h1>
            <p className="text-muted-foreground text-sm">Entre para ver suas medalhas.</p>
        </div>

        {registered && (
            <div className="bg-green-500/10 text-green-600 p-3 rounded-lg text-sm mb-4 text-center border border-green-500/20">
                Conta criada com sucesso! Pode entrar.
            </div>
        )}

        {error && (
            <div className="bg-destructive/10 text-destructive p-3 rounded-lg text-sm mb-4 border border-destructive/20">
                {error}
            </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
            <div>
                <label className="block text-sm font-medium text-foreground mb-1">Usuário</label>
                <input 
                    type="text" 
                    required
                    className="w-full p-2 border border-input rounded-lg focus:ring-2 focus:ring-ring bg-background text-foreground"
                    value={formData.username}
                    onChange={e => setFormData({...formData, username: e.target.value})}
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-foreground mb-1">Senha</label>
                <input 
                    type="password" 
                    required
                    className="w-full p-2 border border-input rounded-lg focus:ring-2 focus:ring-ring bg-background text-foreground"
                    value={formData.password}
                    onChange={e => setFormData({...formData, password: e.target.value})}
                />
            </div>

            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-primary text-primary-foreground py-3 rounded-xl font-bold hover:bg-primary/90 transition"
            >
                {loading ? 'Entrando...' : 'Acessar Painel'}
            </button>
        </form>

        <p className="text-center mt-6 text-sm text-muted-foreground">
            Ainda não tem conta? <Link href="/aluno/signup" className="text-primary hover:underline">Criar agora</Link>
        </p>
         <div className="text-center mt-4">
             <Link href="/aluno" className="text-xs text-muted-foreground hover:underline">Voltar</Link>
        </div>
      </div>
    </div>
  );
}

